import React from 'react';
const DangKyBaiDoXe = () => (
    <div style={{backgroundColor: '#fff', padding: '25px', borderRadius: '15px'}}>
        <h2>🅿️ Đăng ký bãi đỗ xe</h2>
        <p style={{color: '#666'}}>Vui lòng chọn loại xe muốn đăng ký chỗ đỗ:</p>
        <div style={{display: 'flex', gap: '15px', marginTop: '20px'}}>
            <button style={{flex: 1, padding: '20px', borderRadius: '10px', border: '1px solid #4caf50', background: '#e8f5e9'}}>Ô tô</button>
            <button style={{flex: 1, padding: '20px', borderRadius: '10px', border: '1px solid #ddd', background: '#fff'}}>Xe máy</button>
        </div>
        <div style={{marginTop: '20px', padding: '15px', backgroundColor: '#fffbe6', border: '1px solid #ffe58f', borderRadius: '8px'}}>
            ⚠️ Lưu ý: Phí đỗ xe ô tô là 1,000,000đ/tháng.
        </div>
    </div>
);
export default DangKyBaiDoXe;
